namespace sv_43924ccaff3541a78e7992c238384206.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);

public record NotificationPrefs(
    bool EmailNotifications,
    bool PushNotifications,
    bool WeeklyDigest,
    List<string> MutedChannels);

public record SecuritySettings(
    bool TwoFactorEnabled,
    DateTime? LastPasswordChange,
    List<ActiveSession> Sessions);

public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);

public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@namespace sv_43924ccaff3541a78e7992c238384206.Components.Pages.Settings

<nav class="settings-sidebar">
    <h5 class="px-3 py-2 text-muted text-uppercase fw-bold small">Settings</h5>
    <ul class="nav flex-column">
        @foreach (var section in Sections)
        {
            <li class="nav-item">
                <button class="nav-link w-100 text-start @(ActiveSection == section.Key ? "active" : "")"
                        @onclick="() => OnSectionChanged.InvokeAsync(section.Key)">
                    <span class="me-2">@section.Icon</span>
                    @section.Label
                </button>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter, EditorRequired]
    public string ActiveSection { get; set; } = "";

    [Parameter, EditorRequired]
    public EventCallback<string> OnSectionChanged { get; set; }

    private record SidebarItem(string Key, string Label, string Icon);

    private static readonly SidebarItem[] Sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨")
    ];
}

@namespace sv_43924ccaff3541a78e7992c238384206.Components.Pages.Settings

<div class="settings-section">
    <h3 class="mb-4">Profile Settings</h3>

    @if (Profile is null)
    {
        <p class="text-muted">Loading profile...</p>
        return;
    }

    <div class="row">
        <div class="col-md-8">
            <div class="mb-3">
                <label class="form-label fw-semibold">Display Name</label>
                <input type="text" class="form-control" @bind="DisplayName" />
            </div>

            <div class="mb-3">
                <label class="form-label fw-semibold">Email</label>
                <input type="email" class="form-control" @bind="Email" />
            </div>

            <div class="mb-3">
                <label class="form-label fw-semibold">Bio</label>
                <textarea class="form-control" rows="4" @bind="Bio"></textarea>
            </div>
        </div>

        <div class="col-md-4">
            <div class="text-center">
                <label class="form-label fw-semibold d-block">Avatar Preview</label>
                <div class="avatar-preview mb-2">
                    @if (!string.IsNullOrWhiteSpace(AvatarUrl))
                    {
                        <img src="@AvatarUrl" alt="Avatar" class="rounded-circle" style="width:100px;height:100px;object-fit:cover;" />
                    }
                    else
                    {
                        <div class="rounded-circle bg-secondary d-flex align-items-center justify-content-center"
                             style="width:100px;height:100px;margin:0 auto;">
                            <span class="text-white fs-1">👤</span>
                        </div>
                    }
                </div>
                <small class="text-muted text-break">@AvatarUrl</small>
            </div>
        </div>
    </div>

    <div class="d-flex gap-2 mt-3">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@IsSaving">
            @if (IsSaving)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
            }
            Save Changes
        </button>
        <button class="btn btn-outline-secondary" @onclick="Discard" disabled="@IsSaving">
            Discard Changes
        </button>
    </div>

    @if (ShowSuccess)
    {
        <div class="alert alert-success alert-dismissible mt-3 fade show" role="alert">
            Profile saved successfully!
            <button type="button" class="btn-close" @onclick="() => ShowSuccess = false"></button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public UserProfile? Profile { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<UserProfile> OnSave { get; set; }

    private string DisplayName = "";
    private string Email = "";
    private string AvatarUrl = "";
    private string Bio = "";
    private bool IsSaving;
    private bool ShowSuccess;

    protected override void OnParametersSet()
    {
        if (Profile is not null && !_initialized)
        {
            LoadFromProfile(Profile);
            _initialized = true;
        }
    }

    private bool _initialized;

    private void LoadFromProfile(UserProfile p)
    {
        DisplayName = p.DisplayName;
        Email = p.Email;
        AvatarUrl = p.AvatarUrl;
        Bio = p.Bio;
    }

    private async Task SaveAsync()
    {
        IsSaving = true;
        ShowSuccess = false;
        try
        {
            var updated = new UserProfile(DisplayName, Email, AvatarUrl, Bio);
            await OnSave.InvokeAsync(updated);
            ShowSuccess = true;
        }
        finally
        {
            IsSaving = false;
        }
    }

    private void Discard()
    {
        if (Profile is not null)
        {
            LoadFromProfile(Profile);
        }
        ShowSuccess = false;
    }
}

@namespace sv_43924ccaff3541a78e7992c238384206.Components.Pages.Settings

<div class="settings-section">
    <h3 class="mb-4">Notification Preferences</h3>

    @if (Prefs is null)
    {
        <p class="text-muted">Loading notifications...</p>
        return;
    }

    <div class="mb-4">
        <h5 class="mb-3">General</h5>

        <div class="form-check form-switch mb-3">
            <input class="form-check-input" type="checkbox" id="emailNotif" @bind="EmailNotifications" />
            <label class="form-check-label" for="emailNotif">
                Email Notifications
                <small class="d-block text-muted">Receive notifications via email</small>
            </label>
        </div>

        <div class="form-check form-switch mb-3">
            <input class="form-check-input" type="checkbox" id="pushNotif" @bind="PushNotifications" />
            <label class="form-check-label" for="pushNotif">
                Push Notifications
                <small class="d-block text-muted">Receive browser push notifications</small>
            </label>
        </div>

        <div class="form-check form-switch mb-3">
            <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="WeeklyDigest" />
            <label class="form-check-label" for="weeklyDigest">
                Weekly Digest
                <small class="d-block text-muted">Get a weekly summary of activity</small>
            </label>
        </div>
    </div>

    <div class="mb-4">
        <h5 class="mb-3">Muted Channels</h5>
        @if (AllChannels.Count == 0)
        {
            <p class="text-muted">No channels available.</p>
        }
        else
        {
            <div class="list-group">
                @foreach (var channel in AllChannels)
                {
                    var isMuted = MutedChannels.Contains(channel);
                    <label class="list-group-item d-flex align-items-center gap-2">
                        <input class="form-check-input" type="checkbox" checked="@isMuted"
                               @onchange="e => ToggleMute(channel, (bool)(e.Value ?? false))" />
                        <span>@channel</span>
                        @if (isMuted)
                        {
                            <span class="badge bg-warning text-dark ms-auto">Muted</span>
                        }
                    </label>
                }
            </div>
        }
    </div>

    <button class="btn btn-primary" @onclick="SaveAsync" disabled="@IsSaving">
        @if (IsSaving)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Save Preferences
    </button>

    @if (ShowSuccess)
    {
        <div class="alert alert-success alert-dismissible mt-3 fade show" role="alert">
            Notification preferences saved!
            <button type="button" class="btn-close" @onclick="() => ShowSuccess = false"></button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public NotificationPrefs? Prefs { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<NotificationPrefs> OnSave { get; set; }

    /// <summary>All available channel names to show in the mute list.</summary>
    [Parameter]
    public List<string> AllChannels { get; set; } = ["general", "announcements", "random", "engineering", "design"];

    private bool EmailNotifications;
    private bool PushNotifications;
    private bool WeeklyDigest;
    private HashSet<string> MutedChannels = new();
    private bool IsSaving;
    private bool ShowSuccess;
    private bool _initialized;

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !_initialized)
        {
            EmailNotifications = Prefs.EmailNotifications;
            PushNotifications = Prefs.PushNotifications;
            WeeklyDigest = Prefs.WeeklyDigest;
            MutedChannels = new HashSet<string>(Prefs.MutedChannels);
            _initialized = true;
        }
    }

    private void ToggleMute(string channel, bool muted)
    {
        if (muted)
            MutedChannels.Add(channel);
        else
            MutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        IsSaving = true;
        ShowSuccess = false;
        try
        {
            var updated = new NotificationPrefs(EmailNotifications, PushNotifications, WeeklyDigest, MutedChannels.ToList());
            await OnSave.InvokeAsync(updated);
            ShowSuccess = true;
        }
        finally
        {
            IsSaving = false;
        }
    }
}

@namespace sv_43924ccaff3541a78e7992c238384206.Components.Pages.Settings

@if (Session is not null)
{
    <div class="modal-backdrop fade show"></div>
    <div class="modal fade show d-block" tabindex="-1" role="dialog">
        <div class="modal-dialog modal-dialog-centered" role="document">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="Cancel"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke this session?</p>
                    <dl class="row mb-0">
                        <dt class="col-sm-4">Device</dt>
                        <dd class="col-sm-8">@Session.Device</dd>
                        <dt class="col-sm-4">Location</dt>
                        <dd class="col-sm-8">@Session.Location</dd>
                        <dt class="col-sm-4">Last Active</dt>
                        <dd class="col-sm-8">@Session.LastActive.ToString("g")</dd>
                    </dl>
                </div>
                <div class="modal-footer">
                    <button type="button" class="btn btn-secondary" @onclick="Cancel">Cancel</button>
                    <button type="button" class="btn btn-danger" @onclick="Confirm" disabled="@IsRevoking">
                        @if (IsRevoking)
                        {
                            <span class="spinner-border spinner-border-sm me-1"></span>
                        }
                        Revoke Session
                    </button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public ActiveSession? Session { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<string> OnConfirm { get; set; }

    [Parameter, EditorRequired]
    public EventCallback OnCancel { get; set; }

    private bool IsRevoking;

    private async Task Confirm()
    {
        if (Session is null) return;
        IsRevoking = true;
        try
        {
            await OnConfirm.InvokeAsync(Session.Id);
        }
        finally
        {
            IsRevoking = false;
        }
    }

    private async Task Cancel() => await OnCancel.InvokeAsync();
}

@namespace sv_43924ccaff3541a78e7992c238384206.Components.Pages.Settings

<div class="settings-section">
    <h3 class="mb-4">Security Settings</h3>

    @if (Security is null)
    {
        <p class="text-muted">Loading security settings...</p>
        return;
    }

