@namespace sv_43924ccaff3541a78e7992c238384206.Components.Pages.Settings

@if (Session is not null)
{
    <div class="modal-backdrop fade show"></div>
    <div class="modal fade show d-block" tabindex="-1" role="dialog">
        <div class="modal-dialog modal-dialog-centered" role="document">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="Cancel"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke this session?</p>
                    <dl class="row mb-0">
                        <dt class="col-sm-4">Device</dt>
                        <dd class="col-sm-8">@Session.Device</dd>
                        <dt class="col-sm-4">Location</dt>
                        <dd class="col-sm-8">@Session.Location</dd>
                        <dt class="col-sm-4">Last Active</dt>
                        <dd class="col-sm-8">@Session.LastActive.ToString("g")</dd>
                    </dl>
                </div>
                <div class="modal-footer">
                    <button type="button" class="btn btn-secondary" @onclick="Cancel">Cancel</button>
                    <button type="button" class="btn btn-danger" @onclick="Confirm" disabled="@IsRevoking">
                        @if (IsRevoking)
                        {
                            <span class="spinner-border spinner-border-sm me-1"></span>
                        }
                        Revoke Session
                    </button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public ActiveSession? Session { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<string> OnConfirm { get; set; }

    [Parameter, EditorRequired]
    public EventCallback OnCancel { get; set; }

    private bool IsRevoking;

    private async Task Confirm()
    {
        if (Session is null) return;
        IsRevoking = true;
        try
        {
            await OnConfirm.InvokeAsync(Session.Id);
        }
        finally
        {
            IsRevoking = false;
        }
    }

    private async Task Cancel() => await OnCancel.InvokeAsync();
}

@namespace sv_43924ccaff3541a78e7992c238384206.Components.Pages.Settings

<div class="settings-section">
    <h3 class="mb-4">Security Settings</h3>

    @if (Security is null)
    {
        <p class="text-muted">Loading security settings...</p>
        return;
    }

    <!-- Change Password Panel -->
    <div class="card mb-4">
        <div class="card-header d-flex align-items-center justify-content-between"
             role="button" @onclick="() => PasswordPanelOpen = !PasswordPanelOpen">
            <span class="fw-semibold">Change Password</span>
            <span>@(PasswordPanelOpen ? "▲" : "▼")</span>
        </div>
        @if (PasswordPanelOpen)
        {
            <div class="card-body">
                <div class="mb-3">
                    <label class="form-label">Current Password</label>
                    <input type="password" class="form-control" @bind="CurrentPassword" />
                </div>
                <div class="mb-3">
                    <label class="form-label">New Password</label>
                    <input type="password" class="form-control" @bind="NewPassword" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Confirm New Password</label>
                    <input type="password" class="form-control" @bind="ConfirmPassword" />
                </div>

                @if (!string.IsNullOrEmpty(PasswordError))
                {
                    <div class="alert alert-danger py-2">@PasswordError</div>
                }
                @if (PasswordSuccess)
                {
                    <div class="alert alert-success py-2">Password updated successfully!</div>
                }

                <button class="btn btn-primary" @onclick="ChangePasswordAsync" disabled="@IsChangingPassword">
                    @if (IsChangingPassword)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Update Password
                </button>

                @if (Security.LastPasswordChange.HasValue)
                {
                    <small class="text-muted ms-3">
                        Last changed: @Security.LastPasswordChange.Value.ToString("MMM dd, yyyy")
                    </small>
                }
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="card mb-4">
        <div class="card-body d-flex align-items-center justify-content-between">
            <div>
                <h5 class="mb-1">Two-Factor Authentication</h5>
                <span class="badge @(Security.TwoFactorEnabled ? "bg-success" : "bg-secondary")">
                    @(Security.TwoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" checked="@Security.TwoFactorEnabled"
                       @onchange="e => OnToggle2FA.InvokeAsync((bool)(e.Value ?? false))" />
            </div>
        </div>
    </div>

    <!-- Active Sessions -->
    <div class="card">
        <div class="card-header fw-semibold">Active Sessions</div>
        <div class="card-body p-0">
            <div class="table-responsive">
                <table class="table table-hover mb-0">
                    <thead class="table-light">
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th class="text-end">Action</th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in Security.Sessions)
                        {
                            var isCurrent = session == Security.Sessions.FirstOrDefault();
                            <tr>
                                <td>
                                    @session.Device
                                    @if (isCurrent)
                                    {
                                        <span class="badge bg-info ms-1">Current</span>
                                    }
                                </td>
                                <td>@session.Location</td>
                                <td>@session.LastActive.ToString("g")</td>
                                <td class="text-end">
                                    @if (!isCurrent)
                                    {
                                        <button class="btn btn-sm btn-outline-danger"
                                                @onclick="() => SessionToRevoke = session">
                                            Revoke
                                        </button>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        </div>
    </div>

    <RevokeSessionDialog Session="@SessionToRevoke"
                         OnConfirm="HandleRevokeConfirmed"
                         OnCancel="() => SessionToRevoke = null" />
</div>

@code {
    [Parameter, EditorRequired]
    public SecuritySettings? Security { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<string> OnRevokeSession { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<bool> OnToggle2FA { get; set; }

    private bool PasswordPanelOpen;
    private string CurrentPassword = "";
    private string NewPassword = "";
    private string ConfirmPassword = "";
    private string? PasswordError;
    private bool PasswordSuccess;
    private bool IsChangingPassword;
    private ActiveSession? SessionToRevoke;

    private async Task ChangePasswordAsync()
    {
        PasswordError = null;
        PasswordSuccess = false;

        if (string.IsNullOrWhiteSpace(CurrentPassword) || string.IsNullOrWhiteSpace(NewPassword))
        {
            PasswordError = "All password fields are required.";
            return;
        }
        if (NewPassword != ConfirmPassword)
        {
            PasswordError = "New password and confirmation do not match.";
            return;
        }
        if (NewPassword.Length < 8)
        {
            PasswordError = "New password must be at least 8 characters.";
            return;
        }

        IsChangingPassword = true;
        try
        {
            await OnChangePassword.InvokeAsync((CurrentPassword, NewPassword));
            PasswordSuccess = true;
            CurrentPassword = "";
            NewPassword = "";
            ConfirmPassword = "";
        }
        catch (Exception ex)
        {
            PasswordError = ex.Message;
        }
        finally
        {
            IsChangingPassword = false;
        }
    }

    private async Task HandleRevokeConfirmed(string sessionId)
    {
        await OnRevokeSession.InvokeAsync(sessionId);
        SessionToRevoke = null;
    }
}

