@namespace sv_43924ccaff3541a78e7992c238384206.Components.Pages.Settings

<div class="settings-section">
    <h3 class="mb-4">Appearance Settings</h3>

    @if (Appearance is null)
    {
        <p class="text-muted">Loading appearance settings...</p>
        return;
    }

    <div class="row">
        <div class="col-md-6">
            <!-- Theme -->
            <div class="mb-4">
                <label class="form-label fw-semibold">Theme</label>
                <div>
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <div class="form-check form-check-inline">
                            <input class="form-check-input" type="radio" name="theme"
                                   id="theme-@theme" value="@theme"
                                   checked="@(Theme == theme)"
                                   @onchange="() => Theme = theme" />
                            <label class="form-check-label" for="theme-@theme">@theme</label>
                        </div>
                    }
                </div>
            </div>

            <!-- Font Size -->
            <div class="mb-4">
                <label class="form-label fw-semibold">Font Size</label>
                <div>
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <div class="form-check form-check-inline">
                            <input class="form-check-input" type="radio" name="fontSize"
                                   id="font-@size" value="@size"
                                   checked="@(FontSize == size)"
                                   @onchange="() => FontSize = size" />
                            <label class="form-check-label" for="font-@size">@size</label>
                        </div>
                    }
                </div>
            </div>

            <!-- Language -->
            <div class="mb-4">
                <label class="form-label fw-semibold">Language</label>
                <select class="form-select" @bind="Language">
                    <option value="en">English</option>
                    <option value="es">Español</option>
                    <option value="fr">Français</option>
                    <option value="de">Deutsch</option>
                    <option value="ja">日本語</option>
                    <option value="zh">中文</option>
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="mb-4">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="compactMode" @bind="CompactMode" />
                    <label class="form-check-label" for="compactMode">
                        Compact Mode
                        <small class="d-block text-muted">Reduce spacing and padding throughout the UI</small>
                    </label>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@IsSaving">
                @if (IsSaving)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Save
            </button>

            @if (ShowSuccess)
            {
                <div class="alert alert-success alert-dismissible mt-3 fade show" role="alert">
                    Appearance settings saved!
                    <button type="button" class="btn-close" @onclick="() => ShowSuccess = false"></button>
                </div>
            }
        </div>

        <!-- Live Preview -->
        <div class="col-md-6">
            <label class="form-label fw-semibold">Live Preview</label>
            <div class="border rounded @PreviewBgClass" style="@PreviewStyle">
                <div class="@PreviewPaddingClass">
                    <div class="d-flex align-items-center mb-2">
                        <div class="rounded-circle me-2 @PreviewAccentClass" style="width:32px;height:32px;"></div>
                        <div>
                            <div class="fw-bold" style="@PreviewFontStyle">Jane Doe</div>
                            <small class="@PreviewMutedClass">jane.doe@example.com</small>
                        </div>
                    </div>
                    <p class="mb-2" style="@PreviewFontStyle">
                        This is a preview of how your content will appear with the selected settings.
                    </p>
                    <button class="btn btn-sm @PreviewBtnClass">Sample Button</button>
                    <span class="badge @PreviewBadgeClass ms-2">Badge</span>
                    <hr class="@PreviewHrClass" />
                    <div class="d-flex justify-content-between" style="@PreviewFontStyle">
                        <span>Language: @LanguageDisplayName</span>
                        <span>@(CompactMode ? "Compact" : "Standard") layout</span>
                    </div>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public AppearanceSettings? Appearance { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string Theme = "Light";
    private string FontSize = "Medium";
    private string Language = "en";
    private bool CompactMode;
    private bool IsSaving;
    private bool ShowSuccess;
    private bool _initialized;

    protected override void OnParametersSet()
    {
        if (Appearance is not null && !_initialized)
        {
            Theme = Appearance.Theme;
            FontSize = Appearance.FontSize;
            Language = Appearance.Language;
            CompactMode = Appearance.CompactMode;
            _initialized = true;
        }
    }

    private async Task SaveAsync()
    {
        IsSaving = true;
        ShowSuccess = false;
        try
        {
            var updated = new AppearanceSettings(Theme, FontSize, Language, CompactMode);
            await OnSave.InvokeAsync(updated);
            ShowSuccess = true;
        }
        finally
        {
            IsSaving = false;
        }
    }

    // Preview computed properties
    private bool IsDark => Theme == "Dark";

    private string PreviewBgClass => IsDark ? "bg-dark text-light" : "bg-white text-dark";
    private string PreviewPaddingClass => CompactMode ? "p-2" : "p-3";
    private string PreviewAccentClass => IsDark ? "bg-primary" : "bg-primary";
    private string PreviewMutedClass => IsDark ? "text-light opacity-50" : "text-muted";
    private string PreviewBtnClass => IsDark ? "btn-outline-light" : "btn-outline-primary";
    private string PreviewBadgeClass => IsDark ? "bg-light text-dark" : "bg-primary";
    private string PreviewHrClass => IsDark ? "border-light" : "";

    private string PreviewStyle => FontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.15rem;",
        _ => "font-size: 1rem;"
    };

    private string PreviewFontStyle => FontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.15rem;",
        _ => "font-size: 1rem;"
    };

    private string LanguageDisplayName => Language switch
    {
        "es" => "Español",
        "fr" => "Français",
        "de" => "Deutsch",
        "ja" => "日本語",
        "zh" => "中文",
        _ => "English"
    };
}

